  liu("Does it hurt here?", "Прослухайте. Що питає лікар?", ["Чи болить тут", "Де болить", "Відколи болить"], "Does it hurt here?"),
  liu("It's nothing serious. Come back in a week.", "Прослухайте. Що сказав лікар?", ["Нічого серйозного, прийти через тиждень", "Це серйозно, прийти завтра", "Нічого серйозного, приходити не треба"], "Nothing serious, in a week."),
  fb("Is it ___, doctor? — No, it's just a cold.", ["serious", "nothing", "health"], "Is it serious?"),
  fb("Come back ___ a week.", ["in", "for", "since"], "In a week — через тиждень."),
  fb("Does it ___ here? — Yes, a lot.", ["hurt", "hurts", "pain"], "Після does — hurt."),
  bs("Нічого серйозного.", ["It's", "nothing", "serious"], ["anything", "not"], "It's nothing serious."),
